from collections import Counter, defaultdict


def transform(grid):
    """Repeat the shortest consistent color pattern across parallel stripes."""
    h, w = len(grid), len(grid[0])
    key_functions = {
        "row": lambda r, c: r,
        "column": lambda r, c: c,
        "sum_diagonal": lambda r, c: r + c,
        "difference_diagonal": lambda r, c: c - r,
    }

    # Select the stripe direction with the strongest same-color line support.
    lines_by_axis = {}
    scores = {}
    for axis, key_fn in key_functions.items():
        lines = defaultdict(list)
        for r, row in enumerate(grid):
            for c, value in enumerate(row):
                if value != 0:
                    lines[key_fn(r, c)].append(value)
        lines_by_axis[axis] = lines
        scores[axis] = sum(max(Counter(values).values())
                           for values in lines.values())

    axis = max(key_functions, key=lambda name: scores[name])
    key_fn = key_functions[axis]
    samples = {
        key: Counter(values).most_common(1)[0][0]
        for key, values in lines_by_axis[axis].items()
    }

    # Find the shortest cycle that assigns a single color to every sampled stripe.
    period = None
    pattern = None
    for candidate in range(1, 2 * (h + w) + 1):
        trial = {}
        for key, color in samples.items():
            residue = key % candidate
            if residue in trial and trial[residue] != color:
                break
            trial[residue] = color
        else:
            period, pattern = candidate, trial
            break

    if period is None:
        period = 2 * (h + w) + 1
        pattern = {key % period: color for key, color in samples.items()}

    return [
        [pattern.get(key_fn(r, c) % period, 0) for c in range(w)]
        for r in range(h)
    ]
